begin;
create extension if not exists pgtap with schema extensions;
set search_path = public, extensions;
select no_plan();
select ok(not has_function_privilege('anon','public.add_manual_movie(uuid,uuid,jsonb,jsonb)','execute'),'manual requires authentication');
select ok(not has_function_privilege('authenticated','public.import_catalog_movie(uuid,uuid,uuid,jsonb,jsonb,bigint)','execute'),'clients cannot import trusted metadata');
select ok(not has_function_privilege('authenticated','private.add_movie(uuid,uuid,uuid,jsonb,jsonb,bigint)','execute'),'internal helper inaccessible');
select ok(not has_table_privilege('authenticated','private.movie_add_requests','select'),'retry ledger private');
insert into auth.users(id,email) values('13000000-0000-0000-0000-000000000001','add-sql@shogun.test'),('13000000-0000-0000-0000-000000000002','add-other@shogun.test');
select public.import_catalog_movie('13000000-0000-0000-0000-000000000002','43000000-0000-0000-0000-000000000001',
  (select id from public.libraries where owner_id='13000000-0000-0000-0000-000000000002'),'{"title":"Same title","year":2026,"genres":["Drama"]}','["DVD"]',2147000001);
set local role authenticated;
select set_config('request.jwt.claim.sub','13000000-0000-0000-0000-000000000001',true);
select is((select count(*) from public.movies where tmdb_id=2147000001),1::bigint,'provider metadata shared without sharing ownership');
select public.create_collection_library('23000000-0000-0000-0000-000000000001','Add SQL library');
select lives_ok($$select public.add_manual_movie('43000000-0000-0000-0000-000000000002','23000000-0000-0000-0000-000000000001',
  '{"title":"Same title","year":2026,"director":"Director","synopsis":"Story","runtimeMinutes":120,"genres":["Drama"],"posterURL":"https://example.com/poster.jpg"}','["DVD","DVD","Blu-ray"]')$$,'manual metadata and multiple copies save atomically');
select lives_ok($$select public.add_manual_movie('43000000-0000-0000-0000-000000000002','23000000-0000-0000-0000-000000000001',
  '{"title":"Same title","year":2026,"director":"Director","synopsis":"Story","runtimeMinutes":120,"genres":["Drama"],"posterURL":"https://example.com/poster.jpg"}','["DVD","DVD","Blu-ray"]')$$,'retry same request succeeds');
select is((select count(*) from public.movies where source='manual' and created_by=auth.uid()),1::bigint,'manual retry retains UUID');
select is((select count(*) from public.owned_copies),3::bigint,'quantity creates separate rows without retry duplicates');
select is((select director from public.movies where source='manual' and created_by=auth.uid()),'Director','director persists');
select is((select runtime_minutes from public.movies where source='manual' and created_by=auth.uid()),120,'runtime persists');
select is((select genres from public.movies where source='manual' and created_by=auth.uid()),array['Drama'],'genres persist');
select is((select poster_path from public.movies where source='manual' and created_by=auth.uid()),'https://example.com/poster.jpg','poster persists');
select throws_ok($$select public.add_manual_movie('43000000-0000-0000-0000-000000000002','23000000-0000-0000-0000-000000000001','{"title":"Changed"}','["DVD"]')$$,'22023',null,'changed request payload rejected');
select throws_ok($$select public.add_manual_movie('43000000-0000-0000-0000-000000000003','23000000-0000-0000-0000-000000000001','{"title":"Invalid"}','["Tape"]')$$,'22023',null,'invalid format rejected');
select throws_ok($$select public.add_manual_movie('43000000-0000-0000-0000-000000000003','23000000-0000-0000-0000-000000000001','{"title":"Invalid","year":1}','["DVD"]')$$,'23514',null,'invalid year rolls back entire save');
select throws_ok($$select public.add_manual_movie('43000000-0000-0000-0000-000000000003','23000000-0000-0000-0000-000000000001','{"title":"Invalid","posterURL":"http://example.com/p.jpg"}','["DVD"]')$$,'22023',null,'non HTTPS poster rejected');
select throws_ok($$select public.add_manual_movie('43000000-0000-0000-0000-000000000003','23000000-0000-0000-0000-000000000001','{"title":"Invalid"}','[]')$$,'22023',null,'zero copies rejected');
select is((select count(*) from public.movies where source='manual' and created_by=auth.uid()),1::bigint,'failed saves leave no metadata');
reset role;
select public.import_catalog_movie('13000000-0000-0000-0000-000000000001','43000000-0000-0000-0000-000000000004','23000000-0000-0000-0000-000000000001','{"title":"Same title","year":2026,"genres":[]}','["4K UHD"]',2147000001);
select public.import_catalog_movie('13000000-0000-0000-0000-000000000001','43000000-0000-0000-0000-000000000004','23000000-0000-0000-0000-000000000001','{"title":"Provider updated details","genres":[]}','["4K UHD"]',2147000001);
set local role authenticated;
select set_config('request.jwt.claim.sub','13000000-0000-0000-0000-000000000001',true);
select is((select count(*) from public.movies where title='Same title'),2::bigint,'manual and provider identity never merged by title/year');
select is((select count(*) from public.movies where tmdb_id=2147000001),1::bigint,'globally existing provider record reused');
select is((select count(*) from public.owned_copies),4::bigint,'provider retry after metadata change does not duplicate');
select set_config('request.jwt.claim.sub','13000000-0000-0000-0000-000000000002',true);
select throws_ok($$select public.add_manual_movie('43000000-0000-0000-0000-000000000002','23000000-0000-0000-0000-000000000001','{"title":"Same title"}','["DVD"]')$$,'42501',null,'outsider denied even with known request UUID');
reset role;
insert into public.library_memberships(library_id,user_id,role) values('23000000-0000-0000-0000-000000000001','13000000-0000-0000-0000-000000000002','viewer');
set local role authenticated;
select throws_ok($$select public.add_manual_movie('43000000-0000-0000-0000-000000000005','23000000-0000-0000-0000-000000000001','{"title":"Viewer attempt"}','["DVD"]')$$,'42501',null,'viewer denied');
reset role;
update public.library_memberships set role='editor' where library_id='23000000-0000-0000-0000-000000000001' and user_id='13000000-0000-0000-0000-000000000002';
set local role authenticated;
select lives_ok($$select public.add_manual_movie('43000000-0000-0000-0000-000000000005','23000000-0000-0000-0000-000000000001','{"title":"Editor film"}','["DVD"]')$$,'editor can save');
reset role;
delete from public.library_memberships where library_id='23000000-0000-0000-0000-000000000001' and user_id='13000000-0000-0000-0000-000000000002';
set local role authenticated;
select throws_ok($$select public.add_manual_movie('43000000-0000-0000-0000-000000000005','23000000-0000-0000-0000-000000000001','{"title":"Editor film"}','["DVD"]')$$,'42501',null,'revoked editor cannot retry previously saved request');
select * from finish();
rollback;
